        @NotBlank @Size(max = 64) String requestId,
        @NotNull @Min(0) @Max(100_000) Integer dailyTotalCap,
        @NotNull List<@NotNull @Min(0) @Max(100_000) Integer> hourlyBudget,
        @NotNull @Min(0) Long expectedVersion
) {
}

